class Solution {
  private int[] parent;

  private int find(int x) {
    while (parent[x] != x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }

  public int maxActivated(int[][] points) {
    int n = points.length;
    parent = new int[2 * n];
    for (int i = 0; i < 2 * n; i++) parent[i] = i;
    java.util.HashMap<Integer, Integer> xs = new java.util.HashMap<>(),
        ys = new java.util.HashMap<>();
    for (int i = 0; i < n; i++) {
      int xi = xs.computeIfAbsent(points[i][0], k -> xs.size());
      int yi = ys.computeIfAbsent(points[i][1], k -> ys.size());
      parent[find(xi)] = find(n + yi);
    }
    int[] size = new int[2 * n];
    for (int i = 0; i < n; i++) size[find(xs.get(points[i][0]))]++;
    int top1 = 0, top2 = 0;
    for (int s : size) {
      if (s > top1) {
        top2 = top1;
        top1 = s;
      } else if (s > top2) top2 = s;
    }
    return top1 + top2 + 1;
  }
}
